# ===================== 拟合曲线/直线 =====================
# 1. 拟合 pts1：二次曲线 (你的代码用的 polyfit 2)
x1, y1 = pts1[:,0], pts1[:,1]
curve_coeff = np.polyfit(x1, y1, 2)
curve = np.poly1d(curve_coeff)

# 2. 拟合 pts2：直线
x2, y2 = pts2[:,0], pts2[:,1]
line_coeff = np.polyfit(x2, y2, 1)
line = np.poly1d(line_coeff)

# ===================== 生成延长线（向下延伸，适配bottom缺角） =====================
x_ext = np.linspace(1100, 2300, 500)  # 左右延伸
y_curve = curve(x_ext)
y_line = line(x_ext)

# ===================== 绘图 =====================
plt.figure(figsize=(14, 8))
# 原始散点
plt.scatter(pts1[:,0], pts1[:,1], c='red', s=3, label='pts1 (二次曲线)')
plt.scatter(pts2[:,0], pts2[:,1], c='blue', s=3, label='pts2 (直线)')
# 拟合线
plt.plot(x_ext, y_curve, 'r-', linewidth=2, label='曲线拟合结果')
plt.plot(x_ext, y_line, 'b-', linewidth=2, label='直线拟合结果')
# bottom 缺角关键边界：图像下边缘 y=3995
plt.axhline(y=3995, color='orange', linestyle='--', linewidth=2, label='图像下边界 (bottom缺角位置)')

# 图像坐标系：Y轴向下为正（必须反转）
plt.gca().invert_yaxis()
plt.xlabel('X 坐标')
plt.ylabel('Y 坐标 (图像向下)')
plt.title('Bottom缺角 | 曲线+直线 可视化')
plt.legend()
plt.grid(True)
plt.show()

# ===================== 打印核心问题 =====================
print("\n========== 核心问题分析 ==========")
